{"code": "import pytest
import impl


def test_usd_normal_amount():
    """USD with 2 decimal places - normal case."""
    exponents = {'USD': 2}
    assert impl.format_amount('123.45', 'USD', exponents) == '123.45'


def test_usd_round_half_even_up():
    """USD rounding: 2.675 -> 2.68 (round up, 8 is even)."""
    exponents = {'USD': 2}
    assert impl.format_amount('2.675', 'USD', exponents) == '2.68'


def test_usd_round_half_even_down():
    """USD rounding: 2.665 -> 2.66 (round down, 6 is even)."""
    exponents = {'USD': 2}
    assert impl.format_amount('2.665', 'USD', exponents) == '2.66'


def test_jpy_zero_decimals():
    """JPY with 0 decimal places - no decimal point in output."""
    exponents = {'JPY': 0}
    result = impl.format_amount('1234.5', 'JPY', exponents)
    assert result == '1234'
    assert '.' not in result


def test_multiple_currencies():
    """Function should work with multiple currencies in exponents dict."""
    exponents = {'USD': 2, 'JPY': 0, 'KWD': 3}

    assert impl.format_amount('123.45', 'USD', exponents) == '123.45'
    assert impl.format_amount('1234.5', 'JPY', exponents) == '1234'
    assert impl.format_amount('1.2345', 'KWD', exponents) == '1.235'


def test_zero_padding():
    """Amounts with fewer decimals should be zero-padded."""
    exponents = {'USD': 2}
    assert impl.format_amount('1', 'USD', exponents) == '1.00'
    assert impl.format_amount('1.2', 'USD', exponents) == '1.20'


def test_negative_amounts():
    """Negative amounts should preserve sign and round correctly."""
    exponents = {'USD': 2}
    assert impl.format_amount('-123.45', 'USD', exponents) == '-123.45'
    assert impl.format_amount('-2.675', 'USD', exponents) == '-2.68'


def test_negative_zero():
    """Negative amounts rounding to zero should be unsigned."""
    exponents = {'USD': 2, 'JPY': 0}
    assert impl.format_amount('-0.004', 'USD', exponents) == '0.00'
    assert impl.format_amount('-0.4', 'JPY', exponents) == '0'


def test_scientific_notation():
    """Scientific notation should be parsed correctly."""
    exponents = {'USD': 2}
    assert impl.format_amount('1E+2', 'USD', exponents) == '100.00'
    assert impl.format_amount('-1.5e-3', 'USD', exponents) == '0.00'


def test_whitespace_handling():
    """Whitespace should be handled by Decimal parser."""
    exponents = {'USD': 2}
    assert impl.format_amount(' 123.45 ', 'USD', exponents) == '123.45'


def test_large_numbers_no_exponent():
    """Large numbers should not use exponent notation."""
    exponents = {'USD': 2}
    result = impl.format_amount('123456789012345.67', 'USD', exponents)
    assert result == '123456789012345.67'
    assert 'E' not in result


def test_more_or_fewer_decimals():
    """Amounts with different decimal places should be quantized correctly."""
    exponents = {'USD': 2}
    assert impl.format_amount('1.234567', 'USD', exponents) == '1.23'
    assert impl.format_amount('1', 'USD', exponents) == '1.00'


def test_zero_formatting():
    """Zero should format correctly in all cases."""
    exponents = {'USD': 2, 'JPY': 0}
    assert impl.format_amount('0', 'USD', exponents) == '0.00'
    assert impl.format_amount('0.00', 'USD', exponents) == '0.00'
    assert impl.format_amount('0', 'JPY', exponents) == '0'


def test_currency_not_found():
    """Unknown or case-mismatched currency code should raise KeyError."""
    exponents = {'USD': 2}
    with pytest.raises(KeyError):
        impl.format_amount('123.45', 'XXX', exponents)
    with pytest.raises(KeyError):
        impl.format_amount('123.45', 'usd', exponents)


def test_currency_lookup_before_amount_validation():
    """KeyError for invalid currency should come before ValueError for amount."""
    exponents = {'USD': 2}
    with pytest.raises(KeyError):
        impl.format_amount('invalid_amount', 'XXX', exponents)


def test_invalid_amount_empty_and_non_numeric():
    """Empty string and non-numeric text should raise ValueError."""
    exponents = {'USD': 2}
    with pytest.raises(ValueError):
        impl.format_amount('', 'USD', exponents)
    with pytest.raises(ValueError):
        impl.format_amount('abc', 'USD', exponents)


def test_invalid_amount_format():
    """Multiple decimals, commas, spaces, symbols should raise ValueError."""
    exponents = {'USD': 2}
    with pytest.raises(ValueError):
        impl.format_amount('1.2.3', 'USD', exponents)
    with pytest.raises(ValueError):
        impl.format_amount('12,34', 'USD', exponents)
    with pytest.raises(ValueError):
        impl.format_amount('1 000.00', 'USD', exponents)
    with pytest.raises(ValueError):
        impl.format_amount('$1.00', 'USD', exponents)


def test_non_finite_values():
    """Infinity and NaN should raise ValueError."""
    exponents = {'USD': 2}
    with pytest.raises(ValueError):
        impl.format_amount('Infinity', 'USD', exponents)
    with pytest.raises(ValueError):
        impl.format_amount('-Infinity', 'USD', exponents)
    with pytest.raises(ValueError):
        impl.format_amount('NaN', 'USD', exponents)
    with pytest.raises(ValueError):
        impl.format_amount('sNaN', 'USD', exponents)"}
